# Site coordinate features.
#
# A site is described by four numbers: the Earth-centred unit-sphere position
# (x, y, z) and the altitude scaled to roughly unit range. The same convention is
# used for every station, so unseen sites can be generated by supplying their
# coordinates.
from __future__ import annotations

import numpy as np


def site_vector(latitude: float, longitude: float, altitude: float,
                altitude_scale_m: float = 2000.0) -> np.ndarray:
    # Return [x, y, z, altitude / altitude_scale_m] as float32.
    if altitude_scale_m <= 0:
        raise ValueError("site.altitude_scale_m must be positive")
    if not -90.0 <= float(latitude) <= 90.0:
        raise ValueError(f"latitude {latitude} is outside [-90, 90]")
    if not -180.0 <= float(longitude) <= 360.0:
        raise ValueError(f"longitude {longitude} is outside [-180, 360]")
    lat, lon = np.deg2rad(float(latitude)), np.deg2rad(float(longitude))
    cos_lat = np.cos(lat)
    return np.array([cos_lat * np.cos(lon), cos_lat * np.sin(lon), np.sin(lat),
                     float(altitude) / float(altitude_scale_m)], dtype=np.float32)
